#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

/* Provided by the candidate in solution.c */
int modbus_read_response(const uint8_t *frame, size_t len,
                         uint8_t expected_addr, int32_t *value_out);

int main(void)
{
    char line[1024];
    while (fgets(line, sizeof line, stdin) != NULL) {
        uint8_t frame[256];
        size_t len = 0;
        char *p = line;
        char *end;
        unsigned long addr = strtoul(p, &end, 16);
        if (end == p) {
            continue;
        }
        p = end;
        for (;;) {
            unsigned long v = strtoul(p, &end, 16);
            if (end == p || len >= sizeof frame) {
                break;
            }
            frame[len++] = (uint8_t)v;
            p = end;
        }
        int32_t value = 0;
        int rc = modbus_read_response(frame, len, (uint8_t)addr, &value);
        if (rc == 0) {
            printf("OK %d\n", (int)value);
        } else {
            printf("ERR %d\n", rc);
        }
    }
    return 0;
}
